(function(){"use strict";function o(s){return s.normalize("NFKD").replace(/[\u064B-\u065F\u0670\u06D6-\u06ED]/g,"")}let t=[],i=!1;self.onmessage=async s=>{if(s.data.type==="load"){if(i){self.postMessage({type:"ready",count:t.length});return}try{const e=await fetch("/api/localizations");if(!e.ok)throw new Error(`HTTP ${e.status}`);t=await e.json(),i=!0,self.postMessage({type:"ready",count:t.length})}catch{self.postMessage({type:"error",message:"فشل تحميل الترجمات"})}return}if(s.data.type==="search"){if(!i){self.postMessage({type:"error",message:"الترجمات لم تحمل بعد"});return}const e=s.data.query.toLowerCase(),l=o(s.data.query);let c;if(s.data.exact)c=t.filter(r=>r.english.toLowerCase()===e||o(r.arabic)===l);else{const r=t.filter(a=>a.english.toLowerCase()===e||o(a.arabic)===l),n=t.filter(a=>!r.includes(a)&&(a.english.toLowerCase().includes(e)||o(a.arabic).includes(l)));c=[...r,...n]}self.postMessage({type:"results",results:c})}}})();
